PAYLOADS = [
    "x | touch /tmp/pwned",
    "x' | touch /tmp/pwned | '",
    "x$(touch /tmp/pwned)",
]


def exploited(payload):
    try:
        if os.path.exists(MARKER):
            os.remove(MARKER)
    except OSError:
        pass
    try:
        backup.backup_site(payload)
    except Exception:
        pass
    return os.path.exists(MARKER)


sys.exit(0 if any(exploited(p) for p in PAYLOADS) else 1)

